外部ライブラリ（React QueryやSWRなど）を使わずに、**AbortController** を活用して「アンマウント時のクリーンアップ」と「連続リクエストによる競合（Race Condition）」を解決するカスタムフックの実装例を紹介します。

### 実装のポイント
1.  **AbortController**: リクエストを中断するための標準的な仕組みです。新しい検索が始まる際、またはコンポーネントがアンマウントされる際に前のリクエストをキャンセルします。
2.  **Race Conditionの防止**: `AbortController` を使うことで、古いリクエストのレスポンスが遅れて届き、最新の検索結果を上書きしてしまう現象を防ぎます。
3.  **Genericの活用**: 検索結果の型を自由に指定できるようにします。

### コード例

```typescript
import { useState, useEffect } from 'react';

/**
 * 検索APIを呼び出すカスタムフック
 * @param query 検索キーワード
 * @param fetcher APIを叩く関数 (queryとAbortSignalを受け取り、Promiseを返す)
 * @returns {data, isLoading, error}
 */
export function useSearch<T>(
  query: string,
  fetcher: (q: string, signal: AbortSignal) => Promise<T>
) {
  const [data, setData] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    // クエリが空の場合は何もしない（または初期状態に戻す）
    if (!query) {
      setData(null);
      setIsLoading(false);
      setError(null);
      return;
    }

    // AbortControllerのインスタンスを作成
    const controller = new AbortController();
    const { signal } = controller;

    const executeSearch = async () => {
      setIsLoading(true);
      setError(null);

      try {
        const result = await fetcher(query, signal);
        setData(result);
      } catch (err: any) {
        // AbortError（中断によるエラー）の場合は状態を更新しない
        if (err.name === 'AbortError') {
          console.log('Fetch aborted');
          return;
        }
        setError(err instanceof Error ? err : new Error('Unknown error'));
      } finally {
        // 中断されていない場合のみloadingをfalseにする
        if (!signal.aborted) {
          setIsLoading(false);
        }
      }
    };

    executeSearch();

    // クリーンアップ関数
    // 1. コンポーネントがアンマウントされた時
    // 2. queryが変化して次のuseEffectが実行される時
    // の両方で実行される
    return () => {
      controller.abort();
    };
  }, [query, fetcher]); // fetcherを依存配列に入れるため、使う側でuseCallback等でラップすることを推奨

  return { data, isLoading, error };
}
```

### 使い方（コンポーネントでの実装例）

```tsx
import React, { useState, useCallback } from 'react';
import { View, Text, TextInput, ActivityIndicator } from 'react-native';
import { useSearch } from './hooks/useSearch'; // 上記のフックをインポート

// レスポンスの型定義
interface SearchResult {
  id: number;
  title: string;
}

const SearchScreen = () => {
  const [text, setText] = useState('');

  // fetcher関数をuseCallbackでラップして、再レンダリングによる無限ループを防ぐ
  const fetchSearchResults = useCallback(async (query: string, signal: AbortSignal): Promise<SearchResult[]> => {
    const response = await fetch(`https://api.example.com/search?q=${query}`, {
      signal, // ここでAbortSignalを渡すのが重要
    });

    if (!response.ok) {
      throw new Error('Network response was not ok');
    }

    return response.json();
  }, []);

  const { data, isLoading, error } = useSearch(text, fetchSearchResults);

  return (
    <View style={{ padding: 20 }}>
      <TextInput
        value={text}
        onChangeText={setText}
        placeholder="検索キーワードを入力..."
        style={{ borderBottomWidth: 1, marginBottom: 20 }}
      />

      {isLoading && <ActivityIndicator />}
      {error && <Text style={{ color: 'red' }}>Error: {error.message}</Text>}

      {data && (
        <View>
          {data.map((item) => (
            <Text key={item.id}>{item.title}</Text>
          ))}
        </View>
      )}
    </View>
  );
};
```

### 解説

1.  **連続検索への対応**:
    ユーザーが素早く文字を打ち込むと、`query` が頻繁に変化します。`useEffect` のクリーンアップ関数 `controller.abort()` が呼ばれるため、前のリクエストは即座にキャンセルされ、最新のリクエストの結果だけが `setData` に反映されます。

2.  **アンマウントへの対応**:
    ユーザーが検索中に画面を戻った場合、クリーンアップ関数が走り、リクエストが中断されます。これにより、アンマウントされたコンポーネントに対して `setState` を実行しようとして発生するメモリリークや警告を防ぎます。

3.  **AbortErrorのハンドリング**:
    `fetch` を中断すると `AbortError` という名前のエラーが発生します。これは「失敗」ではなく「意図的な中断」なので、`error` ステートを更新しないように `if (err.name === 'AbortError')` で判定しています。

4.  **fetcherの設計**:
    `fetcher` を引数として渡す設計にすることで、このフックを「検索API」だけでなく、他の「取得API」にも再利用できるようにしています。

swift-01.1:
Swift 6の厳格な並行処理（Strict Concurrency）を考慮し、ご要望の要件（古い結果の破棄、キャンセル非協力的なAPIへの対応、DI、エラー処理）をすべて満たす実装例を以下に示します。

### 実装のポイント
1.  **Taskの管理**: `searchTask` を保持し、新しい検索が始まるたびに `cancel()` を呼ぶことで、古いリクエストの結果がUIを上書きするのを防ぎます。
2.  **キャンセル非協力的なAPIへの対応**: `Task.isCancelled` をチェックすることで、ネットワークリクエスト自体は止まらなくても、その結果をUIに反映させないようにします。
3.  **状態管理**: `SearchState` 列挙型を使い、Loading/Success/Error/Idleの状態を明確に分離します。
4.  **依存性の注入**: `SearchService` プロトコルを定義し、ViewModelに注入します。

---

### 実装コード

```swift
import Foundation
import Combine

// MARK: - Models & State
enum SearchState: Equatable {
    case idle
    case loading
    case success([String])
    case error(String)

    static func == (lhs: SearchState, rhs: SearchState) -> Bool {
        switch (lhs, rhs) {
        case (.idle, .idle), (.loading, .loading): return true
        case (.success(let l), .success(let r)): return l == r
        case (.error(let l), .error(let r)): return l == r
        default: return false
        }
    }
}

// MARK: - Service Protocol (Dependency Injection)
protocol SearchService: Sendable {
    func fetchResults(query: String) async throws -> [String]
}

// MARK: - ViewModel
@MainActor
class SearchViewModel: ObservableObject {
    @Published var searchText: String = ""
    @Published private(set) var state: SearchState = .idle

    private let service: SearchService
    private var searchTask: Task<Void, Never>?

    // デバウンス時間（任意：入力のたびにAPIを叩かないようにする）
    private let debounceDelay: UInt64 = 300_000_000 // 0.3秒

    init(service: SearchService) {
        self.service = service
    }

    /// 検索文字列が変わるたびに呼ばれる
    func updateSearchText(_ text: String) {
        searchText = text

        // 前のタスクをキャンセル（古い結果が上書きされるのを防ぐ）
        searchTask?.cancel()

        // 空文字の場合は即座にidleに戻す
        if text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            state = .idle
            return
        }

        // 新しい検索タスクを開始
        searchTask = Task {
            do {
                // デバウンス処理
                try await Task.sleep(nanoseconds: debounceDelay)

                // タスクがキャンセルされたかチェック
                if Task.isCancelled { return }

                state = .loading

                // 非同期検索の実行
                let results = try await service.fetchResults(query: text)

                // 検索完了時にもキャンセルチェック（非協力的なAPI対策）
                // API自体は止まらなくても、この後のUI更新をスキップする
                if Task.isCancelled { return }

                state = .success(results)
            } catch is CancellationError {
                // キャンセル時は何もしない（古いタスクなので）
            } catch {
                // エラー処理
                state = .error(error.localizedDescription)
            }
        }
    }
}

// MARK: - Mock Service (Example)
struct MockSearchService: SearchService {
    func fetchResults(query: String) async throws -> [String] {
        // 擬似的なネットワーク遅延
        try await Task.sleep(nanoseconds: 1_000_000_000)

        // 擬似的なエラー（例：特定の文字でエラー）
        if query == "error" {
            throw NSError(domain: "SearchError", code: -1, userInfo: [NSLocalizedDescriptionKey: "Network failed"])
        }

        return ["Result 1 for \(query)", "Result 2 for \(query)"]
    }
}
```

### 解説

#### 1. 古い結果の上書き防止 (`searchTask?.cancel()`)
`searchTask` 変数に現在の `Task` を保持します。ユーザーが文字を打つたびに、前のタスクを `cancel()` します。これにより、前のリクエストが遅れて戻ってきたとしても、その後の処理（`state = .success`）が実行されないように制御します。

#### 2. キャンセル非協力的なAPIへの対応
`URLSession` などの一部の古いAPIや、内部で `Task` をキャンセルに反応しない処理を行っている場合、`cancel()` を呼んでもネットワーク通信自体は止まりません。
このコードでは、**`await` の直後および `state` を更新する直前**に `if Task.isCancelled { return }` を配置しています。これにより、通信自体はバックグラウンドで走り続けても、**UIを更新する処理だけを確実にブロック**します。

#### 3. Swift 6 の並行処理への適合
- `@MainActor` を ViewModel に付与することで、UI更新に関するデータ競合をコンパイラレベルで防ぎます。
- `SearchService` を `Sendable` に準拠させることで、異なるアクター間での安全なデータ受け渡しを保証します。

#### 4. エラーと空文字の処理
- `text.isEmpty` のチェックにより、空文字の時に無駄なAPIコールを発生させず、状態を `.idle` に戻します。
- `do-catch` ブロックでエラーをキャッチし、`SearchState.error` に格納することで、UI側でエラーメッセージを表示できるようにしています。

### 使い方（SwiftUIの例）

```swift
struct SearchView: View {
    @StateObject private var viewModel = SearchViewModel(service: MockSearchService())

    var body: some View {
        NavigationView {
            VStack {
                TextField("検索キーワードを入力...", text: $viewModel.searchText)
                    .onChange(of: viewModel.searchText) { oldValue, newValue in
                        viewModel.updateSearchText(newValue)
                    }
                    .textFieldStyle(.roundedBorder)
                    .padding()

                ContentSwitcher(state: viewModel.state)
            }
            .navigationTitle("検索")
        }
    }
}

struct ContentSwitcher: View {
    let state: SearchState

    var body: some View {
        switch state {
        case .idle:
            Text("キーワードを入力してください")
        case .loading:
            ProgressView("検索中...")
        case .success(let results):
            List(results, id: \.self) { Text($0) }
        case .error(let message):
            Text("エラー: \(message)").foregroundColor(.red)
        }
    }
}
```

